package com.loopers.interfaces.consumer
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.clients.producer.*;import org.apache.kafka.common.TopicPartition;import org.apache.kafka.common.serialization.StringSerializer;import org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;import java.time.Duration;import java.util.Properties
class KafkaRedeliveryExperimentTest{@Test fun uncommittedSameOffsetRedeliversButEffectIsOnce(){KafkaExperimentSupport().use{k->val t="redelivery-w6";val g="w6-redelivery";k.topic(t,1);val p=Properties();p[ProducerConfig.BOOTSTRAP_SERVERS_CONFIG]=k.broker.bootstrapServers;p[ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG]=StringSerializer::class.java;p[ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG]=StringSerializer::class.java;KafkaProducer<String,String>(p).use{it.send(ProducerRecord(t,"order-1","event-1")).get()};val ledger=mutableSetOf<String>();var deliveries=0;k.consumer(g,"A").use{it.subscribe(listOf(t));val r=one(it);deliveries++;ledger+=r.value()};k.consumer(g,"A").use{it.subscribe(listOf(t));val r=one(it);deliveries++;ledger+=r.value();it.commitSync(mapOf(TopicPartition(t,r.partition()) to OffsetAndMetadata(r.offset()+1)))};assertThat(deliveries).isEqualTo(2);assertThat(ledger).hasSize(1)}};private fun one(c:KafkaConsumer<String,String>):ConsumerRecord<String,String>{repeat(100){val r=c.poll(Duration.ofMillis(100));if(!r.isEmpty)return r.first()};error("no record")}}
